/**
 * The RTMP endpoint to publish to.
 */
data class RtmpDestination (
    /**
     * Server base URL: `rtmp://host[:port]` (port defaults to 1935). Put the
     * app name in [`RtmpDestination::app`], not in the URL.
     */
    var `url`: kotlin.String
    , 
    /**
     * Application name, e.g. `"live"`.
     */
    var `app`: kotlin.String
    , 
    /**
     * Stream key (the publish name). Never logged.
     */
    var `streamKey`: kotlin.String
    , 
    /**
     * Socket read/write timeout in milliseconds. `0` selects the core's 10 s
     * default.
     */
    var `timeoutMs`: kotlin.ULong
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRtmpDestination: FfiConverterRustBuffer<RtmpDestination> {
    override fun read(buf: ByteBuffer): RtmpDestination {
        return RtmpDestination(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: RtmpDestination) = (
            FfiConverterString.allocationSize(value.`url`) +
            FfiConverterString.allocationSize(value.`app`) +
            FfiConverterString.allocationSize(value.`streamKey`) +
            FfiConverterULong.allocationSize(value.`timeoutMs`)
    )

    override fun write(value: RtmpDestination, buf: ByteBuffer) {
            FfiConverterString.write(value.`url`, buf)
            FfiConverterString.write(value.`app`, buf)
            FfiConverterString.write(value.`streamKey`, buf)
            FfiConverterULong.write(value.`timeoutMs`, buf)
    }
}



/**
 * Everything needed to run one publish session.
 *
 * Build one with [`default_session_config`] and adjust the fields you need.
 */
data class SessionConfig (
    /**
     * Where to publish.
     */
    var `destination`: RtmpDestination
    , 
    /**
     * What the encoder produces.
     */
    var `stream`: StreamInfo
    , 
    /**
     * Live-edge behaviour under network pressure.
     */
    var `latency`: LatencyMode
    , 
    /**
     * Reconnect budget: `None` retries forever, `Some(n)` gives up after `n`
     * failed attempts.
     */
    var `reconnectMaxAttempts`: kotlin.UInt?
    , 
    /**
     * Delay before the first scheduled reconnect retry, in milliseconds.
     */
    var `reconnectInitialDelayMs`: kotlin.ULong
    , 
    /**
     * Cap on the exponential reconnect backoff, in milliseconds.
     */
    var `reconnectMaxDelayMs`: kotlin.ULong
    , 
    /**
     * Reconnect when the transport reports no forward progress for this long,
     * in milliseconds.
     */
    var `stallTimeoutMs`: kotlin.ULong
