/**
 * Every way an FFI call can fail. Each variant becomes its own exception
 * type in Kotlin/Swift, carrying the `message`.
 */
sealed class StreamException(message: String): kotlin.Exception(message) {
        
    /**
     * The configuration was rejected (bad URL, empty app/stream key, ...).
     */
        class InvalidConfig(message: String) : StreamException(message)
        
    /**
     * The call does not fit the session's current lifecycle state.
     */
        class InvalidState(message: String) : StreamException(message)
        
    /**
     * The core rejected the operation (codec config, ...).
     */
        class Engine(message: String) : StreamException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<StreamException> {
        override fun lift(error_buf: RustBuffer.ByValue): StreamException = FfiConverterTypeStreamError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeStreamError : FfiConverterRustBuffer<StreamException> {
    override fun read(buf: ByteBuffer): StreamException {
        
            return when(buf.getInt()) {
            1 -> StreamException.InvalidConfig(FfiConverterString.read(buf))
            2 -> StreamException.InvalidState(FfiConverterString.read(buf))
            3 -> StreamException.Engine(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: StreamException): ULong {
        return 4UL
    }

    override fun write(value: StreamException, buf: ByteBuffer) {
        when(value) {
            is StreamException.InvalidConfig -> {
                buf.putInt(1)
                Unit
            }
            is StreamException.InvalidState -> {
                buf.putInt(2)
                Unit
            }
            is StreamException.Engine -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




